import { isNeonApiError, messageFromBody } from "../api.js";
import { isConfigInit, isCurrentBranchProbe } from "../context.js";
import { looksLikeBranchId } from "./formats.js";
//#region src/utils/enrichers.ts
const BRANCHES_LIST_LIMIT = 100;
/**
* Branch list pages cap at 100. A name stored in `.neon` can live on a later
* page, so resolution has to walk `pagination.next` before treating it as missing.
*/
const listAllProjectBranches = async (apiClient, projectId) => {
	const result = [];
	let cursor;
	while (true) {
		const { data } = await apiClient.listProjectBranches({
			projectId,
			limit: BRANCHES_LIST_LIMIT,
			cursor
		});
		result.push(...data.branches);
		cursor = data.pagination?.next;
		if (!cursor || data.branches.length === 0) break;
	}
	return result;
};
const branchIdResolve = async ({ branch, apiClient, projectId }) => {
	branch = branch.toString();
	if (looksLikeBranchId(branch)) return branch;
	const branches = await listAllProjectBranches(apiClient, projectId);
	const branchData = branches.find((b) => b.name === branch);
	if (!branchData) throw new Error(`Branch ${branch} not found.\nAvailable branches: ${branches.map((b) => b.name).join(", ")}`);
	return branchData.id;
};
const getBranchIdFromProps = async (props) => {
	const branch = "branch" in props && typeof props.branch === "string" ? props.branch : props.id;
	if (branch) return await branchIdResolve({
		branch,
		apiClient: props.apiClient,
		projectId: props.projectId
	});
	const defaultBranch = (await listAllProjectBranches(props.apiClient, props.projectId)).find((b) => b.default);
	if (defaultBranch) return defaultBranch.id;
	throw new Error("No default branch found");
};
const branchIdFromProps = async (props) => {
	props.branchId = await getBranchIdFromProps(props);
	return props.branchId;
};
const resolveBranchRef = async (props) => {
	const branch = typeof props.branch === "string" ? props.branch : props.id;
	const branches = await listAllProjectBranches(props.apiClient, props.projectId);
	const listingFields = (listed) => ({
		isDefault: listed.default === true,
		isProtected: listed.protected === true,
		...listed.parent_id ? { parentId: listed.parent_id } : {},
		...listed.expires_at ? { expiresAt: listed.expires_at } : {}
	});
	if (branch) {
		const ref = branch.toString();
		const found = looksLikeBranchId(ref) ? branches.find((b) => b.id === ref) : branches.find((b) => b.name === ref);
		if (found) return {
			branchId: found.id,
			branchName: found.name ?? found.id,
			usedDefault: false,
			...listingFields(found)
		};
		if (looksLikeBranchId(ref)) return {
			branchId: ref,
			branchName: ref,
			usedDefault: false
		};
		throw new Error(`Branch ${ref} not found.\nAvailable branches: ${branches.map((b) => b.name).join(", ")}`);
	}
	const defaultBranch = branches.find((b) => b.default);
	if (!defaultBranch) throw new Error("No default branch found");
	return {
		branchId: defaultBranch.id,
		branchName: defaultBranch.name ?? defaultBranch.id,
		usedDefault: true,
		...listingFields(defaultBranch)
	};
};
const resolveSingleDatabase = async (props) => {
	const { data } = await props.apiClient.listProjectBranchDatabases(props.projectId, props.branchId);
	const databases = data.databases;
	if (props.database !== void 0) {
		if (!databases.find((d) => d.name === props.database)) throw new Error(`Database not found: ${props.database}. Available databases on branch ${props.branchId}: ${databases.map((d) => d.name).join(", ")}`);
		return props.database;
	}
	if (databases.length === 0) throw new Error(`No databases found for the branch: ${props.branchId}`);
	if (databases.length === 1) return databases[0].name;
	throw new Error(`Multiple databases found for the branch, please provide one with the --database option: ${databases.map((d) => d.name).join(", ")}`);
};
const fillSingleProject = async (props) => {
	if (isCurrentBranchProbe(props)) return props;
	if (isConfigInit(props)) return props;
	if (props.projectId) return {
		...props,
		projectId: props.projectId
	};
	let orgId = props.orgId;
	if (!orgId) {
		const { data: orgsData } = await props.apiClient.getCurrentUserOrganizations();
		if (orgsData.organizations.length === 1) orgId = orgsData.organizations[0].id;
	}
	try {
		const { data } = await props.apiClient.listProjects({
			limit: 2,
			org_id: orgId
		});
		if (data.projects.length === 0) throw new Error("No projects found");
		if (data.projects.length > 1) throw new Error(`Multiple projects found, please provide one with the --project-id option`);
		return {
			...props,
			projectId: data.projects[0].id
		};
	} catch (error) {
		if (isNeonApiError(error) && error.status === 400 && messageFromBody(error.data)?.includes("org_id is required")) throw new Error("Multiple projects found, please provide one with the --project-id option");
		throw error;
	}
};
const fillSingleOrg = async (props) => {
	if (props.orgId) return props;
	const { data } = await props.apiClient.getCurrentUserOrganizations();
	if (data.organizations.length === 0) throw new Error("No organizations found");
	if (data.organizations.length > 1) throw new Error(`Multiple organizations found, please provide one with the --org-id option`);
	return {
		...props,
		orgId: data.organizations[0].id
	};
};
//#endregion
export { branchIdFromProps, branchIdResolve, fillSingleOrg, fillSingleProject, listAllProjectBranches, resolveBranchRef, resolveSingleDatabase };
